mapper.select:
SELECT H.*, D.DSN AS DS_NM, D.DBMS_TP AS DS_DBMS_TP
  FROM TB_DATA_MODEL_CHANGE_HISTORY H
  LEFT JOIN TB_DATA_MODEL M ON M.DM_ID = H.DM_ID
  LEFT JOIN ndata.TB_DATA_SOURCE D ON D.DS_ID = M.DM_DS_ID
WHERE 1=1

	AND H.DM_ID = #{dmId}


	AND (H.APRV_STATUS = 'APPROVED' OR H.CHANGE_USER_ID = #{currentUserId})


	AND H.CHANGE_USER_ID = #{changeUserId}


	AND H.CHANGE_TIER = #{changeTier}


	AND H.APRV_STATUS = #{aprvStatus}


	AND H.CHANGE_DT >= #{fromDt}


	AND H.CHANGE_DT <= #{toDt}

ORDER BY H.CHANGE_SEQ DESC
LIMIT 500

SELECT H.SUBMISSION_ID as "submissionId", MAX(H.CHANGE_USER_ID) as "changeUserId", MIN(H.CHANGE_DT) as "firstDt", MAX(H.CHANGE_DT) as "lastDt", COUNT(*) as "itemCnt", MAX(H.DM_ID) as "dmId", STRING_AGG(DISTINCT M.DM_NM, ', ') as "dmNm" FROM TB_DATA_MODEL_CHANGE_HISTORY H LEFT JOIN TB_DATA_MODEL M ON M.DM_ID = H.DM_ID WHERE H.SUBMISSION_ID IS NOT NULL AND H.APRV_STATUS = 'SUBMITTED'
AND H.CHANGE_USER_ID = #{changeUserId}
GROUP BY H.SUBMISSION_ID ORDER BY "firstDt" DESC LIMIT 200

SELECT * FROM TB_DATA_MODEL_CHANGE_HISTORY
WHERE SUBMISSION_ID = #{submissionId}
ORDER BY CHANGE_SEQ ASC

SELECT * FROM TB_DATA_MODEL_CHANGE_HISTORY
WHERE CHANGE_USER_ID = #{currentUserId}
  AND APRV_STATUS = 'DRAFT'

  AND DM_ID = #{dmId}

ORDER BY CHANGE_SEQ ASC

mapper.update:
UPDATE TB_DATA_MODEL_CHANGE_HISTORY
   SET APRV_STATUS  = #{aprvStatus},
       APRV_USER_ID = #{aprvUserId},
       APRV_DT      = #{aprvDt},
       APRV_COMMENT = #{aprvComment, jdbcType=VARCHAR}
 WHERE CHANGE_SEQ = #{changeSeq}
   AND APRV_STATUS IN
   #{s}

UPDATE TB_DATA_MODEL_CHANGE_HISTORY
   SET DDL_EXEC_DT      = #{ddlExecDt},
       DDL_EXEC_USER_ID = #{ddlExecUserId},
       DDL_EXEC_RESULT  = #{ddlExecResult},
       DDL_EXEC_MESSAGE = #{ddlExecMessage, jdbcType=VARCHAR}
       , DDL_SNIPPET = #{ddlSnippet}

       , DDL_EXEC_DONE = NULLIF(#{ddlExecDone}, '')
 WHERE CHANGE_SEQ = #{changeSeq}

UPDATE TB_DATA_MODEL_CHANGE_HISTORY
   SET DDL_EXEC_DT      = #{ddlExecDt},
       DDL_EXEC_USER_ID = #{ddlExecUserId},
       DDL_EXEC_RESULT  = 'SUCCESS',
       DDL_EXEC_MESSAGE = #{ddlExecMessage}
 WHERE DM_ID = #{dmId}
   AND COALESCE(OBJ_OWNER, '') = #{objOwner}
   AND OBJ_NM = #{objNm}
   AND CHANGE_SEQ > #{changeSeq}
   AND APRV_STATUS = 'APPROVED'
   AND DDL_EXEC_DT IS NULL
   AND CHANGE_TYPE IN ('ADD_ATTR', 'MODIFY_ATTR', 'DEL_ATTR', 'ADD_PK', 'DEL_PK', 'ADD_FK', 'DEL_FK')

mapper.delete:
DELETE FROM TB_DATA_MODEL_CHANGE_HISTORY
 WHERE CHANGE_SEQ      = #{changeSeq}
   AND CHANGE_USER_ID  = #{currentUserId}
   AND APRV_STATUS     = 'REJECTED'

mapper.select:
SELECT COUNT(*)
  FROM TB_DATA_MODEL_CHANGE_HISTORY h
 WHERE h.DM_ID = #{dmId}
   AND h.APRV_STATUS IN ('DRAFT', 'SUBMITTED')
   AND h.CHANGE_SEQ NOT IN #{s}
   AND (

       (COALESCE(h.OBJ_OWNER,'') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR},''),'') AND h.OBJ_NM = #{objNm}
        AND h.CHANGE_TYPE IN ('MODIFY_OBJ', 'DEL_OBJ')) OR

       (h.CHANGE_TYPE IN ('ADD_PK', 'DEL_PK', 'ADD_FK', 'DEL_FK') AND EXISTS (
           SELECT 1 FROM TB_DATA_MODEL_CONSTRAINT c
            WHERE c.DM_ID = h.DM_ID AND c.CONSTRAINT_NM = h.CONSTRAINT_NM
              AND COALESCE(c.OBJ_OWNER,'') = COALESCE(h.OBJ_OWNER,'') AND c.TABLE_NM = h.OBJ_NM
              AND ((COALESCE(c.OBJ_OWNER,'') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR},''),'') AND c.TABLE_NM = #{objNm}
                    AND c.COLUMN_NM = #{attrNm})
                OR (COALESCE(c.REF_OWNER,'') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR},''),'') AND c.REF_TABLE_NM = #{objNm}
                    AND c.REF_COLUMN_NM = #{attrNm}))))
   )

mapper.update:
UPDATE TB_DATA_MODEL_ATTR
   SET APRV_STATUS  = #{aprvStatus},
       APRV_USER_ID = #{aprvUserId},
       APRV_DT      = #{aprvDt},
       APRV_COMMENT = #{aprvComment, jdbcType=VARCHAR}
 WHERE DM_ID = #{dmId}
   AND FK_PARENT_OBJ_NM = #{parentObjNm}
   AND FK_PARENT_ATTR_NM = #{parentAttrNm}
   AND COALESCE(FK_PARENT_OBJ_OWNER,'') = COALESCE(NULLIF(#{parentObjOwner, jdbcType=VARCHAR},''),'')
   AND APRV_STATUS IN ('DRAFT', 'SUBMITTED')

UPDATE TB_DATA_MODEL_ATTR
   SET APRV_STATUS  = #{aprvStatus},
       APRV_USER_ID = #{aprvUserId},
       APRV_DT      = #{aprvDt},
       APRV_COMMENT = #{aprvComment, jdbcType=VARCHAR}
 WHERE DM_ID = #{dmId}
   AND OBJ_NM = #{objNm}
   AND COALESCE(OBJ_OWNER,'') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR},''),'')
   AND APRV_STATUS IN ('DRAFT', 'SUBMITTED')

UPDATE TB_DATA_MODEL_CHANGE_HISTORY
   SET APRV_STATUS  = #{aprvStatus},
       APRV_USER_ID = #{aprvUserId},
       APRV_DT      = #{aprvDt},
       APRV_COMMENT = #{aprvComment, jdbcType=VARCHAR}
 WHERE DM_ID = #{dmId}
   AND OBJ_NM = #{objNm}
   AND COALESCE(OBJ_OWNER,'') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR},''),'')
   AND CHANGE_TYPE LIKE '%\_ATTR' ESCAPE '\'
   AND APRV_STATUS IN ('DRAFT', 'SUBMITTED')

mapper.select:
SELECT OBJ_OWNER as objOwner, OBJ_NM as objNm, ATTR_NM as attrNm
  FROM TB_DATA_MODEL_ATTR
 WHERE DM_ID = #{dmId}
   AND FK_PARENT_OBJ_NM  = #{parentObjNm}
   AND FK_PARENT_ATTR_NM = #{parentAttrNm}
   AND COALESCE(FK_PARENT_OBJ_OWNER,'') = COALESCE(NULLIF(#{parentObjOwner, jdbcType=VARCHAR},''),'')
   AND APRV_STATUS IN ('DRAFT', 'SUBMITTED')

SELECT OBJ_OWNER as objOwner, OBJ_NM as objNm, ATTR_NM as attrNm
  FROM TB_DATA_MODEL_ATTR
 WHERE DM_ID = #{dmId}
   AND APRV_STATUS = 'REJECTED'
   AND APRV_DT = #{aprvDt}

mapper.update:
UPDATE TB_DATA_MODEL_ATTR
   SET APRV_STATUS  = #{aprvStatus},
       APRV_USER_ID = #{aprvUserId},
       APRV_DT      = #{aprvDt}
 WHERE DM_ID = #{dmId}
   AND COALESCE(OBJ_OWNER,'') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR},''),'')
   AND OBJ_NM = #{objNm}
   AND ATTR_NM = #{attrNm}

UPDATE TB_DATA_MODEL_OBJ
   SET APRV_STATUS  = #{aprvStatus},
       APRV_USER_ID = #{aprvUserId},
       APRV_DT      = #{aprvDt}
 WHERE DM_ID = #{dmId}
   AND COALESCE(OBJ_OWNER,'') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR},''),'')
   AND OBJ_NM = #{objNm}

UPDATE TB_DATA_MODEL_CONSTRAINT
   SET APRV_STATUS  = #{aprvStatus},
       APRV_USER_ID = #{aprvUserId},
       APRV_DT      = #{aprvDt}
 WHERE DM_ID = #{dmId}
   AND COALESCE(OBJ_OWNER,'') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR},''),'')
   AND TABLE_NM = #{objNm}
   AND CONSTRAINT_NM = #{constraintNm}

UPDATE TB_DATA_MODEL_INDEX
   SET APRV_STATUS  = #{aprvStatus},
       APRV_USER_ID = #{aprvUserId},
       APRV_DT      = #{aprvDt}
 WHERE DM_ID = #{dmId}
   AND COALESCE(OBJ_OWNER,'') = COALESCE(NULLIF(#{objOwner, jdbcType=VARCHAR},''),'')
   AND TABLE_NM = #{objNm}
   AND INDEX_NM = #{indexNm}

